  let state = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (state === 0) {
      if (c === '[') state = 1;
    } else if (state === 1) {
      if (c === '[') state = 2;
    } else if (state === 2) {
      if (c === ']') state = 3;
    } else if (state === 3) {
      if (c === ']') return true;
    }
  }
  return false;
}

function solve(args) {
  const s = args[0];
  let open = 0, maxDepth = 0;
  for (let c of s) {
    if (c === '[') open++;
    else if (c === ']' && open > 0) {
      maxDepth = Math.max(maxDepth, open);
      open--;
    }
  }
  return maxDepth >= 2;
}

function solve(args) {
  const gpas = args[0];
  const thresholds = [3.7, 3.3, 3.0, 2.7, 2.3, 2.0, 1.7, 1.3, 1.0, 0.7, 0.0];
  const letters = ["A", "A-", "B+", "B", "B-", "C+", "C", "C-", "D+", "D", "D-"];
  const result = [];
  for (let i = 0; i < gpas.length; i++) {
    const g = gpas[i];
    if (g === 4) {
      result.push("A+");
    } else if (g === 0) {
      result.push("E");
    } else {
      let grade = "E";
      for (let j = 0; j < thresholds.length; j++) {
        if (g > thresholds[j]) {
          grade = letters[j];
          break;
        }
      }
      result.push(grade);
    }
  }
  return result;
}

function solve(args) {
  const gpas = args[0];
  const thresholds = [
    [3.7, "A"],
    [3.3, "A-"],
    [3.0, "B+"],
    [2.7, "B"],
    [2.3, "B-"],
    [2.0, "C+"],
    [1.7, "C"],
    [1.3, "C-"],
    [1.0, "D+"],
    [0.7, "D"],
    [0.0, "D-"]
  ];
  return gpas.map(gpa => {
    if (gpa === 4) return "A+";
    if (gpa === 0) return "E";
    for (let i = 0; i < thresholds.length; i++) {
      if (gpa > thresholds[i][0]) return thresholds[i][1];
    }
    return "D-";
  });
}
